ST.xhtml:
(* PRG_Axis_Control — 运动独立任务(ETHERCAT 4ms)。只读 AxisCmd_*，写 AxisFb_*/rForceAct。
   禁止被其它 POU CALL；禁止写 HMI_*/报警。
   X：FB_XDual（LineTrack + 双 FB_Servo，无 Virtual/Gear）；Y/Z/R 仍 FB_Servo。 *)

(* ===== 力传感转换（本 POU 拥有 rForceAct） ===== *)
fbForce(wRaw := Force_wInRaw, rScale := Force_rScale, xEnable := Force_xEnable,
    xTare := HMI_xForceTare OR Logic_xForceTare, xUntare := HMI_xForceUntare);
Force_iRaw := fbForce.iRaw;
Force_xCommOk := fbForce.xCommOk;
Force_xTimeout := fbForce.xTimeout;
IF NOT HMI_xForceSimEnable THEN
    rForceAct := fbForce.rForceN;
END_IF;

(* ===== X：FB_XDual（LineTrack + 双 Servo；无 Virtual/Gear） ===== *)
fbX(
    AxisM1 := Axis, AxisM2 := Axis_1,
    xEnable := AxisCmd_xPower, xStop := AxisCmd_xStopAll, xResetFault := AxisCmd_xResetFault,
    xJogPos := AxisCmd_xJogXPos, xJogNeg := AxisCmd_xJogXNeg,
    xSpinLeft := AxisCmd_xSpinLeft, xSpinRight := AxisCmd_xSpinRight,
    xMoveRel := AxisCmd_xMoveRelX, rMoveDist := AxisCmd_rMoveDistX, rMoveVel := AxisCmd_rMoveVelX,
    rJogVel := AxisCmd_rJogVelX, rSpinVel := AxisCmd_rSpinVel,
    rHeadingErr := AxisCmd_rHeadingErr, rKpTrack := AxisCmd_rTrackKp,
    rAcc := AxisCmd_rAccX, rDec := AxisCmd_rDecX,
    rTrimMax := Cfg_rPhaseMax);
AxisFb_xMoveDoneX := fbX.xMoveDone;
AxisFb_rPosX := fbX.rPosV;
AxisFb_rSyncErr := fbX.rSyncErr;
AxisFb_rVelFactorX := fbX.rVelFactor;
AxisFb_xGantryCoupled := fbX.xCoupled;
AxisFb_xInGearM1 := fbX.xInGearM1;
AxisFb_xInGearM2 := fbX.xInGearM2;
AxisFb_xPoweredV := fbX.xPoweredV;
AxisFb_xSyncWarn := fbX.xSyncWarn;
AxisFb_xSyncFault := fbX.xSyncFault;
AxisFb_iGantryState := fbX.iState;
AxisFb_rVelCmdM1 := fbX.rVelCmdM1;
AxisFb_rVelCmdM2 := fbX.rVelCmdM2;
AxisFb_rPosM1 := fbX.rPosM1;
AxisFb_rPosM2 := fbX.rPosM2;
AxisFb_xMovingM1 := fbX.xMovingM1;
AxisFb_xMovingM2 := fbX.xMovingM2;
AxisFb_xStandstill1 := fbX.xStandstillM1;
AxisFb_xStandstill2 := fbX.xStandstillM2;
AxisFb_xPoweredM1 := fbX.xPoweredM1;
AxisFb_xPoweredM2 := fbX.xPoweredM2;
AxisFb_xReadyM1 := fbX.xReadyM1;
AxisFb_xReadyM2 := fbX.xReadyM2;
AxisFb_xFaultM1 := fbX.xFaultM1;
AxisFb_xFaultM2 := fbX.xFaultM2;

(* ===== Y：回零 > 绝对(归位) > 相对(横移) > 点动；硬限位 [Cfg_rLimYNeg, Cfg_rLimYPos] ===== *)
fbY(Axis := Axis_2, xEnable := AxisCmd_xPower, xStop := AxisCmd_xStopAll, xResetFault := AxisCmd_xResetFault,
    xHome := AxisCmd_xHomeY,
    xMoveAbs := AxisCmd_xMoveAbsY, rTargetPos := AxisCmd_rMoveAbsPosY,
    xMoveRel := AxisCmd_xMoveRelY, rDist := AxisCmd_rMoveDistY,
    xJogPos := AxisCmd_xJogYPos, xJogNeg := AxisCmd_xJogYNeg, rJogVel := AxisCmd_rJogVelY,
    rVel := AxisCmd_rMoveVelY, rAcc := AxisCmd_rAccY, rDec := AxisCmd_rDecY,
    xLimEn := TRUE, rLimPos := Cfg_rLimYPos, rLimNeg := Cfg_rLimYNeg);
AxisFb_xMoveDoneY := fbY.xMoveRelDone;

(* ===== Z：力跟随速度 > 回零 > 点动；硬限位 [Cfg_rLimZNeg, Cfg_rLimZPos] ===== *)
fbFF(rForceSet := AxisCmd_rForceSet, rForceAct := rForceAct, rKp := AxisCmd_rForceKp,
    rVelMax := AxisCmd_rForceVelMax, rDeadband := 0.5, rPosZ := fbZ.rActPos,
    rLimPos := Cfg_rLimZPos, rLimNeg := Cfg_rLimZNeg,
    xEnable := AxisCmd_xForceFollow, xInvert := FALSE);
fbZ(Axis := Axis_3, xEnable := AxisCmd_xPower, xStop := AxisCmd_xStopAll, xResetFault := AxisCmd_xResetFault,
    xHome := AxisCmd_xHomeZ,
    xUseVelCmd := AxisCmd_xForceFollow, rVelCmd := fbFF.rZVelCmd,
    xJogPos := AxisCmd_xJogZPos, xJogNeg := AxisCmd_xJogZNeg, rJogVel := AxisCmd_rJogVelZ,
    rAcc := AxisCmd_rAccZ, rDec := AxisCmd_rDecZ,
    xLimEn := TRUE, rLimPos := Cfg_rLimZPos, rLimNeg := Cfg_rLimZNeg);

(* ===== R：回零 > 保持角(绝对) > 点动；M5 门控；硬限位 [Cfg_rLimRNeg, Cfg_rLimRPos] ===== *)
fbR(Axis := Axis_4, xEnable := AxisCmd_xPower AND xM5Ready, xStop := AxisCmd_xStopAll, xResetFault := AxisCmd_xResetFault,
    xHome := AxisCmd_xHomeR,
    xMoveAbs := AxisCmd_xHoldR, rTargetPos := AxisCmd_rRHoldPos,
    xJogPos := AxisCmd_xJogRPos, xJogNeg := AxisCmd_xJogRNeg, rJogVel := AxisCmd_rJogVelR,
    rVel := AxisCmd_rJogVelR, rAcc := AxisCmd_rAccR, rDec := AxisCmd_rDecR,
    xLimEn := TRUE, rLimPos := Cfg_rLimRPos, rLimNeg := Cfg_rLimRNeg);

(* ===== Y/Z/R 反馈回写 ===== *)
AxisFb_rPosY := fbY.rActPos; AxisFb_rPosZ := fbZ.rActPos; AxisFb_rPosR := fbR.rActPos;
AxisFb_xMovingY := fbY.xMoving; AxisFb_xMovingZ := fbZ.xMoving; AxisFb_xMovingR := fbR.xMoving;
AxisFb_xStandstillY := fbY.xStandstill; AxisFb_xStandstillZ := fbZ.xStandstill; AxisFb_xStandstillR := fbR.xStandstill;
AxisFb_xPoweredY := fbY.xPowered; AxisFb_xPoweredZ := fbZ.xPowered; AxisFb_xPoweredR := fbR.xPowered;
AxisFb_xReadyY := fbY.xReady; AxisFb_xReadyZ := fbZ.xReady; AxisFb_xReadyR := fbR.xReady;
AxisFb_xHomedY := fbY.xHomed; AxisFb_xHomedZ := fbZ.xHomed; AxisFb_xHomedR := fbR.xHomed;
AxisFb_xFaultY := fbY.xFault; AxisFb_xFaultZ := fbZ.xFault; AxisFb_xFaultR := fbR.xFault;
AxisFb_xReady := AxisFb_xReadyM1 AND AxisFb_xReadyM2 AND fbY.xReady AND fbZ.xReady
    AND (NOT xM5Ready OR fbR.xReady);

(* FB_XLineTrack — X 直行按航向误差纠偏差速 / 原地左右转。
   eMode: 0=无  1=直行(rBaseVel 带符号 + 纠偏)  2=左旋  3=右旋 *)

rTrim := LIMIT(-ABS(rTrimMax), rKpTrack * rHeadingErr, ABS(rTrimMax));

CASE eMode OF
    1:
        rVelM1 := rBaseVel + rTrim;
        rVelM2 := rBaseVel - rTrim;
    2:
        rVelM1 := ABS(rSpinVel);
        rVelM2 := -ABS(rSpinVel);
    3:
        rVelM1 := -ABS(rSpinVel);
        rVelM2 := ABS(rSpinVel);
ELSE
    rVelM1 := 0.0;
    rVelM2 := 0.0;
END_CASE;

IF xStop OR NOT xEnable THEN
    rVelM1 := 0.0;
    rVelM2 := 0.0;
END_IF;

xActive := (eMode <> 0) AND xEnable AND NOT xStop;

(* FB_XDual — M1/M2 独立速度 + FB_XLineTrack；无 Virtual/Gear。
   走距：平均相对位移；不做 |PosM1-PosM2| 联锁。 *)

(* 废弃同步输出 *)
rSyncErr := 0.0;
rVelFactor := 0.0;
iState := 0;
xCoupled := FALSE;
xInGearM1 := FALSE;
xInGearM2 := FALSE;
xPoweredV := FALSE;
xSyncWarn := FALSE;
xSyncFault := FALSE;

(* 模式：Stop > Spin > Jog/MoveRel（与 tools/x_dual_logic.py 一致；用 IF 避免 SEL 真假序陷阱） *)
IF xStop OR NOT xEnable THEN
    eMode := 0;
    rBase := 0.0;
ELSIF xSpinLeft XOR xSpinRight THEN
    IF xSpinLeft THEN
        eMode := 2;
    ELSE
        eMode := 3;
    END_IF;
    rBase := 0.0;
ELSIF (xJogPos XOR xJogNeg) OR xMoveRel THEN
    eMode := 1;
    IF xMoveRel THEN
        IF rMoveDist >= 0.0 THEN
            rBase := ABS(rMoveVel);
        ELSE
            rBase := -ABS(rMoveVel);
        END_IF;
    ELSIF xJogPos THEN
        rBase := ABS(rJogVel);
    ELSE
        rBase := -ABS(rJogVel);
    END_IF;
ELSE
    eMode := 0;
    rBase := 0.0;
END_IF;

fbTrack(
    xEnable := xEnable,
    xStop := xStop,
    eMode := eMode,
    rBaseVel := rBase,
    rSpinVel := rSpinVel,
    rHeadingErr := rHeadingErr,
    rKpTrack := rKpTrack,
    rTrimMax := rTrimMax
);
rVelCmdM1 := fbTrack.rVelM1;
rVelCmdM2 := fbTrack.rVelM2;

fbM1(
    Axis := AxisM1,
    xEnable := xEnable,
    xStop := xStop,
    xResetFault := xResetFault,
    xUseVelCmd := TRUE,
    rVelCmd := rVelCmdM1,
    rAcc := rAcc,
    rDec := rDec,
    xLimEn := FALSE
);
fbM2(
    Axis := AxisM2,
    xEnable := xEnable,
    xStop := xStop,
    xResetFault := xResetFault,
    xUseVelCmd := TRUE,
    rVelCmd := rVelCmdM2,
    rAcc := rAcc,
    rDec := rDec,
    xLimEn := FALSE
);

rPosM1 := LREAL_TO_REAL(fbM1.rActPos);
rPosM2 := LREAL_TO_REAL(fbM2.rActPos);
rAvg := (rPosM1 + rPosM2) * 0.5;
rPosV := rAvg;
xMovingM1 := fbM1.xMoving;
xMovingM2 := fbM2.xMoving;
xStandstillM1 := fbM1.xStandstill;
xStandstillM2 := fbM2.xStandstill;
xPoweredM1 := fbM1.xPowered;
xPoweredM2 := fbM2.xPowered;
xReadyM1 := fbM1.xReady;
xReadyM2 := fbM2.xReady;
xFaultM1 := fbM1.xFault;
xFaultM2 := fbM2.xFault;

(* 走距完成：上升沿锁平均位；|Δavg|≥|dist| 保持 done，直至撤销/Stop（对齐 move_done_update） *)
IF xStop OR NOT xEnable OR NOT xMoveRel THEN
    xArmed := FALSE;
    xMoveDone := FALSE;
ELSE
    IF xMoveRel AND NOT xMovePrev THEN
        xArmed := TRUE;
        rStart := rAvg;
    END_IF;
    xMoveDone := xArmed AND (ABS(rAvg - rStart) >= ABS(rMoveDist));
END_IF;
xMovePrev := xMoveRel;

(* FB_Force — Modbus 原始力换算 + 软件去皮 + 通讯看门狗（仅提示，不进故障） *)

iRaw := WORD_TO_INT(wRaw);
rRawScaled := INT_TO_REAL(iRaw) * rScale;

IF xTare AND NOT xTarePrev THEN
    rTare := rRawScaled;
END_IF;
xTarePrev := xTare;
IF xUntare AND NOT xUntarePrev THEN
    rTare := 0.0;
END_IF;
xUntarePrev := xUntare;

rForceN := rRawScaled - rTare;

tonStale(IN := xEnable AND (wRaw = wPrev), PT := T#2S);
wPrev := wRaw;
xTimeout := xEnable AND tonStale.Q;
xCommOk := xEnable AND NOT xTimeout;

(* PRG_TcpHmi — Modbus TCP 过程映像编解码 + 控制源仲裁。
   PLC=Master 读 Holding1000 / 写 Holding1100；Gateway=Server。
   eCtrlSrc 为 GVL 变量：0=面板/触摸屏 1=远程(Web)。 *)

IF NOT xInit THEN
    Tcp_xEStop := TRUE;
    Tcp_rJogVelX := 0.4; Tcp_rSpinVel := 0.3;
    Tcp_rJogVelY := 0.3; Tcp_rJogVelZ := 0.2; Tcp_rJogVelR := 0.2;
    Tcp_rAutoDistX := 1.0; Tcp_rAutoVelX := 0.4;
    Tcp_rAutoVelY := 0.3; Tcp_rAutoVelZ := 0.15;
    Tcp_rWheelBase := 5.0; Tcp_rForceSet := 100.0;
    Tcp_xForceSimEnable := FALSE;
    Tcp_iAutoPasses := 1;
    Tcp_rHeadingErr := 0.0;
    Tcp_rKpTrack := 0.0; Tcp_rKpForce := 1.0;
    Tcp_rAccX := 100.0; Tcp_rDecX := 100.0;
    Tcp_rAccY := 100.0; Tcp_rDecY := 100.0;
    Tcp_rAccZ := 100.0; Tcp_rDecZ := 100.0;
    Tcp_rAccR := 100.0; Tcp_rDecR := 100.0;
    Tcp_iCommStatus := 0;
    Tcp_wLastHb := 0; Tcp_wLastSeq := 16#FFFF; Tcp_wStatusSeq := 0;
    tonHb(IN := FALSE);
    xInit := TRUE;
END_IF;

(* ===== 命令快照解码 ===== *)
wMagic := MB_CmdIn[0];
wVersion := MB_CmdIn[1];
wSeqHead := MB_CmdIn[2];
wHeartbeat := MB_CmdIn[3];
wSeqTail := MB_CmdIn[63];
xValid := (wMagic = 19533) AND (wVersion = 256) AND (wSeqHead = wSeqTail);
IF xValid THEN
    Tcp_iCommStatus := 1;
    IF wHeartbeat <> Tcp_wLastHb THEN
        tonHb(IN := FALSE);
        tonHb(IN := TRUE, PT := T#1S);
        Tcp_wLastHb := wHeartbeat;
    END_IF;
    IF wSeqHead <> Tcp_wLastSeq THEN
        Tcp_wLastSeq := wSeqHead;
        Tcp_xEStop := (MB_CmdIn[4] AND 1) <> 0;
        Tcp_xStop := (MB_CmdIn[4] AND 2) <> 0;
        Tcp_xStopHold3s := (MB_CmdIn[4] AND 4) <> 0;
        Tcp_xStart := (MB_CmdIn[4] AND 8) <> 0;
        Tcp_xEnable := (MB_CmdIn[4] AND 16) <> 0;
        Tcp_xAutoMode := (MB_CmdIn[4] AND 32) <> 0;
        Tcp_xJogXPos := (MB_CmdIn[4] AND 64) <> 0;
        Tcp_xJogXNeg := (MB_CmdIn[4] AND 128) <> 0;
        Tcp_xSpinLeft := (MB_CmdIn[4] AND 256) <> 0;
        Tcp_xSpinRight := (MB_CmdIn[4] AND 512) <> 0;
        Tcp_xJogYPos := (MB_CmdIn[4] AND 1024) <> 0;
        Tcp_xJogYNeg := (MB_CmdIn[4] AND 2048) <> 0;
        Tcp_xJogZPos := (MB_CmdIn[4] AND 4096) <> 0;
        Tcp_xJogZNeg := (MB_CmdIn[4] AND 8192) <> 0;
        Tcp_xJogRPos := (MB_CmdIn[4] AND 16384) <> 0;
        Tcp_xJogRNeg := (MB_CmdIn[4] AND 32768) <> 0;
        Tcp_xHomeY := (MB_CmdIn[5] AND 1) <> 0;
        Tcp_xHomeZ := (MB_CmdIn[5] AND 2) <> 0;
        Tcp_xHomeR := (MB_CmdIn[5] AND 4) <> 0;
        Tcp_xHomeExec := (MB_CmdIn[5] AND 8) <> 0;
        Tcp_xAutoStart := (MB_CmdIn[5] AND 16) <> 0;
        Tcp_xAutoAbort := (MB_CmdIn[5] AND 32) <> 0;
        Tcp_xForceSimEnable := (MB_CmdIn[5] AND 64) <> 0;
        Tcp_xForceTare := (MB_CmdIn[5] AND 128) <> 0;
        Tcp_xForceUntare := (MB_CmdIn[5] AND 256) <> 0;
        Tcp_xForceGuide := (MB_CmdIn[5] AND 512) <> 0;
        Tcp_iHomeAxis := WORD_TO_INT(MB_CmdIn[6]);
        Tcp_iAutoPasses := WORD_TO_INT(MB_CmdIn[7]);
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[8]), 16) OR WORD_TO_DWORD(MB_CmdIn[9]);
        Tcp_rJogVelX := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[10]), 16) OR WORD_TO_DWORD(MB_CmdIn[11]);
        Tcp_rSpinVel := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[12]), 16) OR WORD_TO_DWORD(MB_CmdIn[13]);
        Tcp_rJogVelY := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[14]), 16) OR WORD_TO_DWORD(MB_CmdIn[15]);
        Tcp_rJogVelZ := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[16]), 16) OR WORD_TO_DWORD(MB_CmdIn[17]);
        Tcp_rJogVelR := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[18]), 16) OR WORD_TO_DWORD(MB_CmdIn[19]);
        Tcp_rAutoDistX := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[20]), 16) OR WORD_TO_DWORD(MB_CmdIn[21]);
        Tcp_rAutoVelX := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[22]), 16) OR WORD_TO_DWORD(MB_CmdIn[23]);
        Tcp_rAutoVelY := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[24]), 16) OR WORD_TO_DWORD(MB_CmdIn[25]);
        Tcp_rAutoVelZ := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[26]), 16) OR WORD_TO_DWORD(MB_CmdIn[27]);
        Tcp_rWheelBase := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[28]), 16) OR WORD_TO_DWORD(MB_CmdIn[29]);
        Tcp_rForceSet := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 100.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[30]), 16) OR WORD_TO_DWORD(MB_CmdIn[31]);
        Tcp_rForceSim := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 100.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[32]), 16) OR WORD_TO_DWORD(MB_CmdIn[33]);
        Tcp_rHeadingErr := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[34]), 16) OR WORD_TO_DWORD(MB_CmdIn[35]);
        Tcp_rKpTrack := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[36]), 16) OR WORD_TO_DWORD(MB_CmdIn[37]);
        Tcp_rKpForce := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[38]), 16) OR WORD_TO_DWORD(MB_CmdIn[39]);
        Tcp_rAccX := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[40]), 16) OR WORD_TO_DWORD(MB_CmdIn[41]);
        Tcp_rDecX := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[42]), 16) OR WORD_TO_DWORD(MB_CmdIn[43]);
        Tcp_rAccY := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[44]), 16) OR WORD_TO_DWORD(MB_CmdIn[45]);
        Tcp_rDecY := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[46]), 16) OR WORD_TO_DWORD(MB_CmdIn[47]);
        Tcp_rAccZ := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[48]), 16) OR WORD_TO_DWORD(MB_CmdIn[49]);
        Tcp_rDecZ := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[50]), 16) OR WORD_TO_DWORD(MB_CmdIn[51]);
        Tcp_rAccR := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
        dwTmp := SHL(WORD_TO_DWORD(MB_CmdIn[52]), 16) OR WORD_TO_DWORD(MB_CmdIn[53]);
        Tcp_rDecR := DINT_TO_REAL(DWORD_TO_DINT(dwTmp)) / 1000.0;
    END_IF;
ELSIF wMagic <> 0 AND wMagic <> 19533 THEN
    Tcp_iCommStatus := 2;
ELSIF wSeqHead <> wSeqTail THEN
    Tcp_iCommStatus := 3;
END_IF;
tonHb();
IF tonHb.Q OR Tcp_iCommStatus = 0 THEN
    Tcp_xTimeout := TRUE;
    Tcp_xConnected := FALSE;
    Tcp_xOnline := FALSE;
    IF tonHb.Q THEN Tcp_iCommStatus := 4; END_IF;
    Tcp_xJogXPos := FALSE; Tcp_xJogXNeg := FALSE;
    Tcp_xSpinLeft := FALSE; Tcp_xSpinRight := FALSE;
    Tcp_xJogYPos := FALSE; Tcp_xJogYNeg := FALSE;
    Tcp_xJogZPos := FALSE; Tcp_xJogZNeg := FALSE;
    Tcp_xJogRPos := FALSE; Tcp_xJogRNeg := FALSE;
    Tcp_xHomeY := FALSE; Tcp_xHomeZ := FALSE; Tcp_xHomeR := FALSE;
    Tcp_xHomeExec := FALSE;
    Tcp_xStart := FALSE; Tcp_xEnable := FALSE;
    Tcp_xAutoStart := FALSE;
    Tcp_xForceTare := FALSE; Tcp_xForceUntare := FALSE; Tcp_xForceGuide := FALSE;
    Tcp_xStop := TRUE;
    Tcp_xAutoAbort := TRUE;
    Tcp_xEStop := TRUE;
ELSE
    Tcp_xTimeout := FALSE;
    Tcp_xConnected := TRUE;
    Tcp_xOnline := TRUE;
END_IF;

(* ===== 状态快照编码 ===== *)
Tcp_wStatusSeq := Tcp_wStatusSeq + 1;
MB_StatusOut[0] := 19533;
MB_StatusOut[1] := 256;
MB_StatusOut[2] := Tcp_wStatusSeq;
MB_StatusOut[3] := Tcp_wLastSeq;
MB_StatusOut[4] := Tcp_wLastHb;
FOR i := 5 TO 62 DO MB_StatusOut[i] := 0; END_FOR;
MB_StatusOut[5] := INT_TO_WORD(Tcp_iCommStatus);
MB_StatusOut[6] := INT_TO_WORD(HMI_eDevState);
MB_StatusOut[7] := INT_TO_WORD(HMI_eOpMode);
MB_StatusOut[8] := INT_TO_WORD(HMI_iAlarmShow);
MB_StatusOut[9] := INT_TO_WORD(HMI_iAutoStepShow);
IF HMI_xDevStop THEN MB_StatusOut[10] := MB_StatusOut[10] OR 1; END_IF;
IF HMI_xDevRun THEN MB_StatusOut[10] := MB_StatusOut[10] OR 2; END_IF;
IF HMI_xDevError THEN MB_StatusOut[10] := MB_StatusOut[10] OR 4; END_IF;
IF HMI_xLampEStop THEN MB_StatusOut[10] := MB_StatusOut[10] OR 8; END_IF;
IF HMI_xLampEnableOk THEN MB_StatusOut[10] := MB_StatusOut[10] OR 16; END_IF;
IF HMI_xLampFault THEN MB_StatusOut[10] := MB_StatusOut[10] OR 32; END_IF;
IF HMI_xAutoBusy THEN MB_StatusOut[10] := MB_StatusOut[10] OR 64; END_IF;
IF HMI_xAutoDone THEN MB_StatusOut[10] := MB_StatusOut[10] OR 128; END_IF;
IF HMI_xHomedY THEN MB_StatusOut[10] := MB_StatusOut[10] OR 256; END_IF;
IF HMI_xHomedZ THEN MB_StatusOut[10] := MB_StatusOut[10] OR 512; END_IF;
IF HMI_xHomedR THEN MB_StatusOut[10] := MB_StatusOut[10] OR 1024; END_IF;
IF HMI_xHomeBusyY THEN MB_StatusOut[10] := MB_StatusOut[10] OR 2048; END_IF;
IF HMI_xHomeBusyZ THEN MB_StatusOut[10] := MB_StatusOut[10] OR 4096; END_IF;
IF HMI_xHomeBusyR THEN MB_StatusOut[10] := MB_StatusOut[10] OR 8192; END_IF;
IF Tcp_xConnected THEN MB_StatusOut[10] := MB_StatusOut[10] OR 16384; END_IF;
IF Tcp_xTimeout THEN MB_StatusOut[10] := MB_StatusOut[10] OR 32768; END_IF;
IF Force_xCommOk THEN MB_StatusOut[11] := MB_StatusOut[11] OR 1; END_IF;
IF Force_xTimeout THEN MB_StatusOut[11] := MB_StatusOut[11] OR 2; END_IF;
IF Force_xSlaveFail THEN MB_StatusOut[11] := MB_StatusOut[11] OR 4; END_IF;
IF Force_xTareBusy THEN MB_StatusOut[11] := MB_StatusOut[11] OR 8; END_IF;
IF Force_xTareDone THEN MB_StatusOut[11] := MB_StatusOut[11] OR 16; END_IF;
IF AxisFb_xReady THEN MB_StatusOut[11] := MB_StatusOut[11] OR 32; END_IF;
IF AxisFb_xMoveDoneX THEN MB_StatusOut[11] := MB_StatusOut[11] OR 64; END_IF;
IF AxisFb_xMoveDoneY THEN MB_StatusOut[11] := MB_StatusOut[11] OR 128; END_IF;
IF AxisFb_xFaultM1 THEN MB_StatusOut[11] := MB_StatusOut[11] OR 256; END_IF;
IF AxisFb_xFaultM2 THEN MB_StatusOut[11] := MB_StatusOut[11] OR 512; END_IF;
IF AxisFb_xFaultY THEN MB_StatusOut[11] := MB_StatusOut[11] OR 1024; END_IF;
IF AxisFb_xFaultZ THEN MB_StatusOut[11] := MB_StatusOut[11] OR 2048; END_IF;
IF AxisFb_xFaultR THEN MB_StatusOut[11] := MB_StatusOut[11] OR 4096; END_IF;
IF AxisFb_xHomedY THEN MB_StatusOut[11] := MB_StatusOut[11] OR 8192; END_IF;
IF AxisFb_xHomedZ THEN MB_StatusOut[11] := MB_StatusOut[11] OR 16384; END_IF;
IF AxisFb_xHomedR THEN MB_StatusOut[11] := MB_StatusOut[11] OR 32768; END_IF;
diTmp := REAL_TO_DINT(HMI_rForceShow * 100.0);
dwTmp := DINT_TO_DWORD(diTmp);
MB_StatusOut[12] := DWORD_TO_WORD(SHR(dwTmp, 16));
MB_StatusOut[13] := DWORD_TO_WORD(dwTmp AND 16#FFFF);
diTmp := REAL_TO_DINT(AxisFb_rPosM1 * 1000.0);
dwTmp := DINT_TO_DWORD(diTmp);
MB_StatusOut[14] := DWORD_TO_WORD(SHR(dwTmp, 16));
MB_StatusOut[15] := DWORD_TO_WORD(dwTmp AND 16#FFFF);
diTmp := REAL_TO_DINT(AxisFb_rPosM2 * 1000.0);
dwTmp := DINT_TO_DWORD(diTmp);
MB_StatusOut[16] := DWORD_TO_WORD(SHR(dwTmp, 16));
MB_StatusOut[17] := DWORD_TO_WORD(dwTmp AND 16#FFFF);
diTmp := REAL_TO_DINT(AxisFb_rPosY * 1000.0);
dwTmp := DINT_TO_DWORD(diTmp);
MB_StatusOut[18] := DWORD_TO_WORD(SHR(dwTmp, 16));
MB_StatusOut[19] := DWORD_TO_WORD(dwTmp AND 16#FFFF);
diTmp := REAL_TO_DINT(AxisFb_rPosZ * 1000.0);
dwTmp := DINT_TO_DWORD(diTmp);
MB_StatusOut[20] := DWORD_TO_WORD(SHR(dwTmp, 16));
MB_StatusOut[21] := DWORD_TO_WORD(dwTmp AND 16#FFFF);
diTmp := REAL_TO_DINT(AxisFb_rPosR * 1000.0);
dwTmp := DINT_TO_DWORD(diTmp);
MB_StatusOut[22] := DWORD_TO_WORD(SHR(dwTmp, 16));
MB_StatusOut[23] := DWORD_TO_WORD(dwTmp AND 16#FFFF);
diTmp := REAL_TO_DINT(AxisFb_rVelCmdM1 * 1000.0);
dwTmp := DINT_TO_DWORD(diTmp);
MB_StatusOut[24] := DWORD_TO_WORD(SHR(dwTmp, 16));
MB_StatusOut[25] := DWORD_TO_WORD(dwTmp AND 16#FFFF);
diTmp := REAL_TO_DINT(AxisFb_rVelCmdM2 * 1000.0);
dwTmp := DINT_TO_DWORD(diTmp);
MB_StatusOut[26] := DWORD_TO_WORD(SHR(dwTmp, 16));
MB_StatusOut[27] := DWORD_TO_WORD(dwTmp AND 16#FFFF);
MB_StatusOut[63] := Tcp_wStatusSeq;

(* ===== 控制源仲裁 ===== *)
xPanelOp := StartBtn OR StopBtn OR ResetBtn OR JogFwd OR JogBwd OR JogLeft OR JogRight
    OR JogUp OR JogDown OR JogClockAdd OR JogClockMis;
xTcpOp := Tcp_xOnline AND (
    Tcp_xStart OR Tcp_xStop OR Tcp_xStopHold3s OR Tcp_xAutoStart OR Tcp_xAutoAbort
    OR Tcp_xJogXPos OR Tcp_xJogXNeg OR Tcp_xSpinLeft OR Tcp_xSpinRight
    OR Tcp_xJogYPos OR Tcp_xJogYNeg OR Tcp_xJogZPos OR Tcp_xJogZNeg
    OR Tcp_xJogRPos OR Tcp_xJogRNeg
    OR Tcp_xHomeY OR Tcp_xHomeZ OR Tcp_xHomeR OR Tcp_xHomeExec
    OR Tcp_xForceGuide OR Tcp_xForceTare OR Tcp_xForceUntare);
IF NOT Tcp_xOnline THEN
    eCtrlSrc := 0;
ELSIF xTcpOp THEN
    eCtrlSrc := 1;
ELSIF xPanelOp THEN
    eCtrlSrc := 0;
END_IF;

IF eCtrlSrc = 1 THEN
    HMI_xAutoMode := Tcp_xAutoMode;
    HMI_xJogXPos := Tcp_xJogXPos;   HMI_xJogXNeg := Tcp_xJogXNeg;
    HMI_xSpinLeft := Tcp_xSpinLeft; HMI_xSpinRight := Tcp_xSpinRight;
    HMI_xJogYPos := Tcp_xJogYPos;   HMI_xJogYNeg := Tcp_xJogYNeg;
    HMI_xJogZPos := Tcp_xJogZPos;   HMI_xJogZNeg := Tcp_xJogZNeg;
    HMI_xJogRPos := Tcp_xJogRPos;   HMI_xJogRNeg := Tcp_xJogRNeg;
    HMI_xHomeY := Tcp_xHomeY; HMI_xHomeZ := Tcp_xHomeZ; HMI_xHomeR := Tcp_xHomeR;
    HMI_iHomeAxis := Tcp_iHomeAxis; HMI_xHomeExec := Tcp_xHomeExec;
    HMI_xForceGuide := Tcp_xForceGuide;
    HMI_xForceTare := Tcp_xForceTare; HMI_xForceUntare := Tcp_xForceUntare;
    HMI_xForceSimEnable := Tcp_xForceSimEnable;
    HMI_rJogVelX := Tcp_rJogVelX; HMI_rSpinVel := Tcp_rSpinVel;
    HMI_rJogVelY := Tcp_rJogVelY; HMI_rJogVelZ := Tcp_rJogVelZ; HMI_rJogVelR := Tcp_rJogVelR;
    HMI_rAutoDistX := Tcp_rAutoDistX; HMI_rAutoVelX := Tcp_rAutoVelX;
    HMI_rAutoVelY := Tcp_rAutoVelY; HMI_rAutoVelZ := Tcp_rAutoVelZ;
    HMI_rWheelBase := Tcp_rWheelBase; HMI_rForceSet := Tcp_rForceSet;
    HMI_rForceSim := Tcp_rForceSim;
    HMI_iAutoPasses := Tcp_iAutoPasses;
    HMI_rHeadingErr := Tcp_rHeadingErr;
    HMI_rKpTrack := Tcp_rKpTrack;
    HMI_rKpForce := Tcp_rKpForce;
    HMI_rAccX := Tcp_rAccX; HMI_rDecX := Tcp_rDecX;
    HMI_rAccY := Tcp_rAccY; HMI_rDecY := Tcp_rDecY;
    HMI_rAccZ := Tcp_rAccZ; HMI_rDecZ := Tcp_rDecZ;
    HMI_rAccR := Tcp_rAccR; HMI_rDecR := Tcp_rDecR;
END_IF;

HMI_xEStop := EStop AND Tcp_xEStop AND HMI_xEStopReq;
HMI_xStart := StartBtn OR HMI_xStartReq OR (Tcp_xOnline AND Tcp_xStart);
HMI_xEnable := HMI_xStart;
HMI_xStop := StopBtn OR HMI_xStopReq OR (Tcp_xOnline AND Tcp_xStop);
HMI_xStopHold3s := ResetBtn OR HMI_xResetReq OR (Tcp_xOnline AND Tcp_xStopHold3s);
HMI_xAutoStart := (Tcp_xOnline AND Tcp_xAutoStart) OR ((eCtrlSrc = 0) AND HMI_xAutoStartReq);
HMI_xAutoAbort := HMI_xAutoAbortReq OR (Tcp_xOnline AND Tcp_xAutoAbort);

(* FB_ForceFollow — Z 恒力 P 控制律；向下=负增压；硬限位 [rLimNeg, rLimPos] 内跟随 *)

IF NOT xEnable THEN
    rZVelCmd := 0.0;
    xInBand := FALSE;
    RETURN;
END_IF;

rErr := rForceSet - rForceAct;
rV := -rKp * rErr;
IF xInvert THEN
    rV := -rV;
END_IF;
rV := LIMIT(-ABS(rVelMax), rV, ABS(rVelMax));

xInBand := ABS(rErr) < rDeadband;
IF xInBand THEN
    rV := 0.0;
END_IF;

(* 硬限位：越限方向输出 0（FB_Servo 另有最终闸门） *)
IF (rPosZ >= rLimPos) AND (rV > 0.0) THEN
    rV := 0.0;
END_IF;
IF (rPosZ <= rLimNeg) AND (rV < 0.0) THEN
    rV := 0.0;
END_IF;

rZVelCmd := rV;

(* MainTask 入口：HMI 交互 -> 设备逻辑；PRG_Axis_Control 在 ETHERCAT 任务独立运行 *)
PRG_TcpHmi();
PRG_Logic();

(* PRG_Logic — 消费已仲裁 HMI_* + 面板键；写 AxisCmd_*；状态只读派生（无状态机耦合）。
   禁止 CALL Axis / FB_Servo。 *)

(* ===== 急停锁存 / 长按复位 ===== *)
IF NOT HMI_xEStop THEN
    xEStopLatched := TRUE;
END_IF;
tonHold(IN := HMI_xStop AND HMI_xEStop, PT := T#3S);
xResetPulse := (HMI_xStopHold3s OR tonHold.Q) AND NOT xResetPrev;
xResetPrev := HMI_xStopHold3s OR tonHold.Q;
IF xResetPulse THEN
    xEStopLatched := FALSE;
    AxisCmd_xResetFault := TRUE;
    iAutoStep := 0;
    iPass := 0;
    Force_xSlaveFail := FALSE;
ELSE
    AxisCmd_xResetFault := FALSE;
END_IF;

(* 故障汇总：各轴 Errorstop（同步跳闸已废，不再 OR AxisFb_xSyncFault） *)
xFaultAggregate := AxisFb_xFaultM1 OR AxisFb_xFaultM2 OR AxisFb_xFaultY OR AxisFb_xFaultZ
    OR (xM5Ready AND AxisFb_xFaultR);

IF HMI_xAutoMode THEN eOpMode := 1; ELSE eOpMode := 0; END_IF;
HMI_eOpMode := eOpMode;

(* 安全 / 使能 —— 去耦：只看急停 + 故障 *)
xSafe := HMI_xEStop AND NOT xEStopLatched;
AxisCmd_xPower := xSafe;
AxisCmd_xStopAll := HMI_xStop OR NOT xSafe OR xFaultAggregate OR HMI_xAutoAbort;

(* 力/纠偏参数下发 *)
rForceKp := HMI_rKpForce;
IF rForceKp < 1.0E-6 THEN rForceKp := 1.0; END_IF;
AxisCmd_rForceSet := HMI_rForceSet;
AxisCmd_rForceKp := rForceKp;
AxisCmd_rForceVelMax := ABS(HMI_rAutoVelZ);
IF AxisCmd_rForceVelMax < 1.0E-6 THEN AxisCmd_rForceVelMax := ABS(HMI_rJogVelZ); END_IF;
AxisCmd_rHeadingErr := HMI_rHeadingErr;

IF HMI_xForceSimEnable THEN
    rForceAct := HMI_rForceSim;
END_IF;
HMI_rForceShow := rForceAct;

AxisCmd_rJogVelX := HMI_rJogVelX;
AxisCmd_rSpinVel := HMI_rSpinVel;
AxisCmd_rJogVelY := HMI_rJogVelY;
AxisCmd_rJogVelZ := HMI_rJogVelZ;
AxisCmd_rJogVelR := HMI_rJogVelR;
AxisCmd_rWheelBase := LIMIT(4.0, HMI_rWheelBase, 6.0);
(* 每轴加减速（RETAIN 参数；<1 时兜底 100） *)
AxisCmd_rAccX := HMI_rAccX; IF AxisCmd_rAccX < 1.0 THEN AxisCmd_rAccX := 100.0; END_IF;
AxisCmd_rDecX := HMI_rDecX; IF AxisCmd_rDecX < 1.0 THEN AxisCmd_rDecX := 100.0; END_IF;
AxisCmd_rAccY := HMI_rAccY; IF AxisCmd_rAccY < 1.0 THEN AxisCmd_rAccY := 100.0; END_IF;
AxisCmd_rDecY := HMI_rDecY; IF AxisCmd_rDecY < 1.0 THEN AxisCmd_rDecY := 100.0; END_IF;
AxisCmd_rAccZ := HMI_rAccZ; IF AxisCmd_rAccZ < 1.0 THEN AxisCmd_rAccZ := 100.0; END_IF;
AxisCmd_rDecZ := HMI_rDecZ; IF AxisCmd_rDecZ < 1.0 THEN AxisCmd_rDecZ := 100.0; END_IF;
AxisCmd_rAccR := HMI_rAccR; IF AxisCmd_rAccR < 1.0 THEN AxisCmd_rAccR := 100.0; END_IF;
AxisCmd_rDecR := HMI_rDecR; IF AxisCmd_rDecR < 1.0 THEN AxisCmd_rDecR := 100.0; END_IF;

(* 限位联锁：物理限位输入 ∨ 可配置硬限位（Cfg_rLim*，FB_Servo 内另有最终闸门） *)
xIlk_BlockYPlus := I_xLimYPos OR (AxisFb_rPosY >= Cfg_rLimYPos);
xIlk_BlockYNeg := I_xLimYNeg OR (AxisFb_rPosY <= Cfg_rLimYNeg);
xIlk_BlockZPlus := I_xLimZPos OR (AxisFb_rPosZ >= Cfg_rLimZPos);
xIlk_BlockZNeg := I_xLimZNeg OR (AxisFb_rPosZ <= Cfg_rLimZNeg);

(* 每拍清命令 *)
AxisCmd_xJogXPos := FALSE; AxisCmd_xJogXNeg := FALSE;
AxisCmd_xSpinLeft := FALSE; AxisCmd_xSpinRight := FALSE;
AxisCmd_xJogYPos := FALSE; AxisCmd_xJogYNeg := FALSE;
AxisCmd_xJogZPos := FALSE; AxisCmd_xJogZNeg := FALSE;
AxisCmd_xJogRPos := FALSE; AxisCmd_xJogRNeg := FALSE;
AxisCmd_xForceFollow := FALSE;
AxisCmd_xMoveRelX := FALSE;
AxisCmd_xMoveRelY := FALSE;
AxisCmd_xMoveAbsY := FALSE;
AxisCmd_xHoldR := FALSE;
AxisCmd_rTrackKp := 0.0;
Logic_xForceTare := FALSE;

xAutoStartEdge := HMI_xAutoStart AND NOT xAutoStartPrev;
xAutoStartPrev := HMI_xAutoStart;

IF HMI_xAutoAbort OR NOT xSafe OR xFaultAggregate THEN
    iAutoStep := 0;
    iPass := 0;
    HMI_xAutoBusy := FALSE;
END_IF;

(* ===== 点动源合并：面板键（仅面板/触摸屏源时）OR 触摸屏/Web ===== *)
xPanelSrc := (eCtrlSrc = 0);
xJogXPosM := HMI_xJogXPos OR (xPanelSrc AND JogFwd);
xJogXNegM := HMI_xJogXNeg OR (xPanelSrc AND JogBwd);
xJogYPosM := HMI_xJogYPos OR (xPanelSrc AND JogRight);
xJogYNegM := HMI_xJogYNeg OR (xPanelSrc AND JogLeft);
xJogZPosM := HMI_xJogZPos OR (xPanelSrc AND JogUp);
xJogZNegM := HMI_xJogZNeg OR (xPanelSrc AND JogDown);
xJogRPosM := HMI_xJogRPos OR (xPanelSrc AND JogClockAdd);
xJogRNegM := HMI_xJogRNeg OR (xPanelSrc AND JogClockMis);

(* ===== 手动 ===== *)
IF xSafe AND (eOpMode = 0) AND NOT HMI_xStop AND NOT xFaultAggregate THEN
    IF HMI_xSpinLeft XOR HMI_xSpinRight THEN
        AxisCmd_xSpinLeft := HMI_xSpinLeft;
        AxisCmd_xSpinRight := HMI_xSpinRight;
    ELSIF xJogXPosM XOR xJogXNegM THEN
        AxisCmd_xJogXPos := xJogXPosM;
        AxisCmd_xJogXNeg := xJogXNegM;
    END_IF;
    AxisCmd_xJogYPos := xJogYPosM AND NOT xIlk_BlockYPlus;
    AxisCmd_xJogYNeg := xJogYNegM AND NOT xIlk_BlockYNeg;
    IF HMI_xForceGuide THEN
        AxisCmd_xForceFollow := TRUE;
    ELSE
        AxisCmd_xJogZPos := xJogZPosM AND NOT xIlk_BlockZPlus;
        AxisCmd_xJogZNeg := xJogZNegM AND NOT xIlk_BlockZNeg;
    END_IF;
    IF xM5Ready THEN
        AxisCmd_xJogRPos := xJogRPosM;
        AxisCmd_xJogRNeg := xJogRNegM;
    END_IF;
END_IF;

(* ===== 自动多道循环 ===== *)
IF xSafe AND (eOpMode = 1) AND NOT HMI_xStop AND NOT xFaultAggregate THEN
    IF iAutoStep = 0 AND xAutoStartEdge THEN
        rRHold := AxisFb_rPosR;
        xAutoTareSent := FALSE;
        HMI_xAutoDone := FALSE;
        HMI_xAutoBusy := TRUE;
        iPass := 1;
        iAutoStep := 1;
    END_IF;

    CASE iAutoStep OF
        1:
            AxisCmd_xHoldR := TRUE;
            AxisCmd_rRHoldPos := rRHold;
            AxisCmd_rTrackKp := HMI_rKpTrack;
            AxisCmd_rMoveDistX := HMI_rAutoDistX;
            AxisCmd_rMoveVelX := HMI_rAutoVelX;
            AxisCmd_xMoveRelX := TRUE;
            IF AxisFb_xMoveDoneX THEN
                AxisCmd_xMoveRelX := FALSE;
                iAutoStep := 2;
            END_IF;
        2:
            AxisCmd_xHoldR := TRUE;
            AxisCmd_rRHoldPos := rRHold;
            AxisCmd_rMoveAbsPosY := 0.0;
            AxisCmd_rMoveVelY := HMI_rAutoVelY;
            AxisCmd_xMoveAbsY := TRUE;
            IF AxisFb_xStandstillY AND (ABS(AxisFb_rPosY) < 0.005) THEN
                AxisCmd_xMoveAbsY := FALSE;
                xAutoTareSent := FALSE;
                iAutoStep := 3;
            END_IF;
        3:
            AxisCmd_xHoldR := TRUE;
            AxisCmd_rRHoldPos := rRHold;
            IF NOT xAutoTareSent THEN
                Logic_xForceTare := TRUE;
                xAutoTareSent := TRUE;
            END_IF;
            AxisCmd_xForceFollow := TRUE;
            IF rForceAct >= HMI_rForceSet THEN
                iAutoStep := 4;
            END_IF;
        4:
            AxisCmd_xHoldR := TRUE;
            AxisCmd_rRHoldPos := rRHold;
            AxisCmd_xForceFollow := TRUE;
            AxisCmd_rMoveDistY := AxisCmd_rWheelBase;
            AxisCmd_rMoveVelY := HMI_rAutoVelY;
            AxisCmd_xMoveRelY := TRUE;
            IF AxisFb_xMoveDoneY THEN
                AxisCmd_xMoveRelY := FALSE;
                iAutoStep := 5;
            END_IF;
        5:
            IF iPass < HMI_iAutoPasses THEN
                iPass := iPass + 1;
                iAutoStep := 1;
            ELSE
                iAutoStep := 6;
            END_IF;
        6:
            HMI_xAutoBusy := FALSE;
            HMI_xAutoDone := TRUE;
            iAutoStep := 0;
            iPass := 0;
    END_CASE;
END_IF;

(* ===== 回零：Y/Z/R；同时只回一轴 ===== *)
xHomeTrigY := HMI_xHomeY OR ((HMI_iHomeAxis = 1) AND HMI_xHomeExec);
xHomeTrigZ := HMI_xHomeZ OR ((HMI_iHomeAxis = 2) AND HMI_xHomeExec);
xHomeTrigR := HMI_xHomeR OR ((HMI_iHomeAxis = 3) AND HMI_xHomeExec);
xAnyHomeBusy := AxisCmd_xHomeY OR AxisCmd_xHomeZ OR AxisCmd_xHomeR;

IF AxisCmd_xStopAll OR NOT xSafe OR xFaultAggregate THEN
    AxisCmd_xHomeY := FALSE;
    AxisCmd_xHomeZ := FALSE;
    AxisCmd_xHomeR := FALSE;
ELSE
    IF AxisCmd_xHomeY AND AxisFb_xHomedY THEN AxisCmd_xHomeY := FALSE; END_IF;
    IF AxisCmd_xHomeZ AND AxisFb_xHomedZ THEN AxisCmd_xHomeZ := FALSE; END_IF;
    IF AxisCmd_xHomeR AND AxisFb_xHomedR THEN AxisCmd_xHomeR := FALSE; END_IF;
    IF (eOpMode = 0) AND NOT HMI_xStop THEN
        IF xHomeTrigY AND NOT xHomeTrigYPrev AND NOT xAnyHomeBusy THEN
            AxisCmd_xHomeY := TRUE;
        ELSIF xHomeTrigZ AND NOT xHomeTrigZPrev AND NOT xAnyHomeBusy THEN
            AxisCmd_xHomeZ := TRUE;
        ELSIF xHomeTrigR AND NOT xHomeTrigRPrev AND NOT xAnyHomeBusy AND xM5Ready THEN
            AxisCmd_xHomeR := TRUE;
        END_IF;
    END_IF;
END_IF;
xHomeTrigYPrev := xHomeTrigY;
xHomeTrigZPrev := xHomeTrigZ;
xHomeTrigRPrev := xHomeTrigR;

IF AxisCmd_xHomeY THEN AxisCmd_xJogYPos := FALSE; AxisCmd_xJogYNeg := FALSE; END_IF;
IF AxisCmd_xHomeZ THEN AxisCmd_xJogZPos := FALSE; AxisCmd_xJogZNeg := FALSE; AxisCmd_xForceFollow := FALSE; END_IF;
IF AxisCmd_xHomeR THEN AxisCmd_xJogRPos := FALSE; AxisCmd_xJogRNeg := FALSE; END_IF;

HMI_xHomedY := AxisFb_xHomedY;
HMI_xHomedZ := AxisFb_xHomedZ;
HMI_xHomedR := AxisFb_xHomedR;
HMI_xHomeBusyY := AxisCmd_xHomeY;
HMI_xHomeBusyZ := AxisCmd_xHomeZ;
HMI_xHomeBusyR := AxisCmd_xHomeR;

(* 使能就绪诊断 → 1007 *)
xReadyAll := AxisFb_xReadyM1 AND AxisFb_xReadyM2 AND AxisFb_xReadyY AND AxisFb_xReadyZ
    AND (NOT xM5Ready OR AxisFb_xReadyR);
tonReady(IN := AxisCmd_xPower AND NOT xReadyAll AND NOT xFaultAggregate, PT := T#2S);

(* 报警 *)
IF xEStopLatched OR NOT HMI_xEStop THEN
    iAlarmID := 1001;
ELSIF AxisFb_xFaultM1 OR AxisFb_xFaultM2 OR AxisFb_xFaultY OR AxisFb_xFaultZ
        OR (xM5Ready AND AxisFb_xFaultR) THEN
    iAlarmID := 1002;
ELSIF tonReady.Q THEN
    iAlarmID := 1007;
ELSIF NOT HMI_xForceSimEnable AND Force_xSlaveFail THEN
    iAlarmID := 1006;
ELSIF NOT HMI_xForceSimEnable AND Force_xTimeout THEN
    iAlarmID := 1005;
ELSE
    iAlarmID := 0;
END_IF;

(* 状态灯（只读派生，不互锁） *)
Dev_xError := xFaultAggregate;
Dev_xRun := xSafe AND NOT HMI_xStop AND NOT xFaultAggregate;
Dev_xStop := NOT Dev_xRun AND NOT Dev_xError;
HMI_xDevError := Dev_xError;
HMI_xDevRun := Dev_xRun;
HMI_xDevStop := Dev_xStop;
IF Dev_xError THEN HMI_eDevState := 2;
ELSIF Dev_xRun THEN HMI_eDevState := 1;
ELSE HMI_eDevState := 0; END_IF;

HMI_iAutoStepShow := iAutoStep;
HMI_xLampEStop := xEStopLatched OR NOT HMI_xEStop;
HMI_xLampEnableOk := Dev_xRun;
HMI_xLampFault := xFaultAggregate;
HMI_iAlarmShow := iAlarmID;

StopLamp := Dev_xStop;
StartLamp := Dev_xRun;

(* =============================================================================
   FB_Servo — 单轴原子封装（SM3_Basic）。仅在 PRG_Axis_Control 任务内实例化。

   仲裁优先级：停止/故障 > 回零 > 绝对定位 > 相对定位 > 速度指令 > 点动。
   - 手动点动走 MC_Jog（松开即减速停）；速度指令走 MC_MoveVelocity
   - 运动切换靠 PLCopen 中止机制（新命令 FB 上升沿自动 abort 旧运动）
   - 全部运动请求撤销（松手/速度归零/停止/急停/撞限位）→ MC_Halt 减速停车
   - 硬限位：xLimEn=TRUE 时，所有模式都限制在 [rLimNeg, rLimPos] 内：
     点动/速度 越限方向被禁止；定位目标被夹紧；X 轴传 xLimEn:=FALSE
   ========================================================================== *)

(* 1. 状态与位置 *)
fbReadStatus(Axis := Axis, Enable := TRUE);
fbReadPos(Axis := Axis, Enable := TRUE);
rActPos := fbReadPos.Position;
xStandstill := fbReadStatus.StandStill;
xFault := fbReadStatus.ErrorStop;
xMoving := fbReadStatus.DiscreteMotion OR fbReadStatus.ContinuousMotion OR fbReadStatus.Homing;

(* 2. 故障复位（上升沿） *)
fbReset(Axis := Axis, Execute := xResetFault AND NOT xResetPrev);
xResetPrev := xResetFault;

(* 3. 驱动器使能（xStop 不掉使能） *)
fbPower(Axis := Axis, Enable := TRUE,
        bRegulatorOn := xEnable AND NOT xFault,
        bDriveStart := xEnable AND NOT xFault);
xPowered := fbPower.Status;
xReady := xPowered AND NOT xFault;

(* 4. 硬限位：越限方向禁止；定位目标夹紧（已越限时仍允许向回运动） *)
xBlockPos := xLimEn AND (rActPos >= rLimPos);
xBlockNeg := xLimEn AND (rActPos <= rLimNeg);
rAbsTarget := rTargetPos;
rRelDist := rDist;
IF xLimEn THEN
    rAbsTarget := LIMIT(rLimNeg, rTargetPos, rLimPos);
    rRelDist := LIMIT(rLimNeg, rActPos + rDist, rLimPos) - rActPos;
END_IF;

(* 5. 命令仲裁：停止/故障 > 回零 > 绝对 > 相对 > 速度 > 点动 *)
xReqStop := xStop OR NOT xEnable OR xFault;
xReqHome := xHome AND NOT xReqStop;
xReqAbs := xMoveAbs AND xPowered AND NOT xReqStop AND NOT xReqHome;
xReqRel := xMoveRel AND (ABS(rRelDist) > 1.0E-9) AND xPowered
           AND NOT xReqStop AND NOT xReqHome AND NOT xReqAbs;
xReqVel := xUseVelCmd AND (ABS(rVelCmd) > 1.0E-6) AND xPowered
           AND NOT ((rVelCmd > 0.0) AND xBlockPos) AND NOT ((rVelCmd < 0.0) AND xBlockNeg)
           AND NOT xReqStop AND NOT xReqHome AND NOT xReqAbs AND NOT xReqRel;
xReqJogPos := xJogPos AND NOT xJogNeg AND NOT xBlockPos AND xPowered
              AND NOT xReqStop AND NOT xReqHome AND NOT xReqAbs AND NOT xReqRel AND NOT xReqVel;
xReqJogNeg := xJogNeg AND NOT xJogPos AND NOT xBlockNeg AND xPowered
              AND NOT xReqStop AND NOT xReqHome AND NOT xReqAbs AND NOT xReqRel AND NOT xReqVel;
xReqAny := xReqHome OR xReqAbs OR xReqRel OR xReqVel OR xReqJogPos OR xReqJogNeg;

(* 6. 回零：MC_Home(0) → MC_SetPosition(0) → xHomed *)
IF xReqHome AND NOT xReqHomePrev THEN
    xHomed := FALSE;
END_IF;
xReqHomePrev := xReqHome;
fbHome(Axis := Axis, Execute := xReqHome, Position := 0.0);
IF fbHome.Done THEN
    xSetZeroTrig := TRUE;
END_IF;
fbSetPos(Axis := Axis, Execute := xSetZeroTrig, Position := 0.0);
IF fbSetPos.Done THEN
    xHomed := TRUE;
    xSetZeroTrig := FALSE;
END_IF;

(* 7. 绝对 / 相对定位（目标已夹紧；电平保持 Execute，Done 上报） *)
fbMoveAbs(Axis := Axis, Execute := xReqAbs, Position := rAbsTarget,
          Velocity := ABS(rVel), Acceleration := rAcc, Deceleration := rDec);
fbMoveRel(Axis := Axis, Execute := xReqRel, Distance := rRelDist,
          Velocity := ABS(rVel), Acceleration := rAcc, Deceleration := rDec);
xMoveAbsDone := fbMoveAbs.Done;
xMoveRelDone := fbMoveRel.Done;

(* 8. 速度指令：MC_MoveVelocity；Velocity 取绝对值，方向走 Direction *)
(* 注意：本机 SM3 库的方向字面值是 positive/negative（非 CoDeSys 的 mcPositiveDirection） *)
IF rVelCmd >= 0.0 THEN
    eDir := positive;
ELSE
    eDir := negative;
END_IF;
(* 运行中换向：先撤 Execute 一拍，下一拍带新方向重新触发 *)
xDirFlip := xReqVel AND xVelRunPrev AND ((rVelCmd >= 0.0) <> (rVelInPrev >= 0.0));
fbMoveVel(Axis := Axis, Execute := xReqVel AND NOT xDirFlip,
          Velocity := ABS(rVelCmd), Direction := eDir,
          Acceleration := rAcc, Deceleration := rDec);
xVelRunPrev := xReqVel;
rVelInPrev := rVelCmd;

(* 9. 手动点动：MC_Jog（按住动、松开减速停；越限方向已在仲裁禁止） *)
fbJog(Axis := Axis,
      JogForward := xReqJogPos,
      JogBackward := xReqJogNeg,
      Velocity := ABS(rJogVel),
      Acceleration := rAcc,
      Deceleration := rDec);

(* 10. 停车：有使能但无任何运动请求（松手/速度归零/停止/急停/撞限位）→ MC_Halt *)
xNeedStop := xPowered AND NOT xReqAny;
fbHalt(Axis := Axis, Execute := xNeedStop AND xMoving AND NOT xHaltPrev,
       Deceleration := rDec);
xHaltPrev := xNeedStop AND xMoving;
